function checked_cocki() {
let cockies = document.getElementById("cockie_container_id");
if (document.cookie) {
    console.log(cockies.style.display = "none");
  } else {
      console.log(cockies.style.display = "block");
  }   
}

    let cockies_button = document.getElementById("cockie_button_ok");
   
    cockies_button.addEventListener("click", function(){
        let cockies = document.getElementById("cockie_container_id");
            
    
  if (document.cookie = "cockies = accepted") {
      console.log(cockies.style.display = "none");
    } else {
        console.log(cockies.style.display = "block");
    }   
 });


 let cockies_button_loeschen = document.getElementById("cockie_button_löschen");
 
 cockies_button_loeschen.addEventListener("click", function(){
 
    if(document.cookie = "cockies = accepted"){
        let n = "cockies"; 
        document.cookie = n+'=; expires=Thu, 01-Jan-70 00:00:01 GMT;';
        localStorage.cookie.removeItem("cockie");
        cockies.style.display = "block";
    console.log("Cockie wurde gelöscht");
     
};
});
